"""Comprehensive tests for compress_string and ThreadSafeLRUCache."""

import threading
import time

import pytest

from compress_string import (
    ThreadSafeLRUCache,
    compress_string,
    decompress_string,
    get_cache,
)


# ── compress_string / decompress_string ──────────────────────────────────────


class TestCompressString:
    def test_round_trip(self):
        original = "hello world " * 100
        compressed = compress_string(original)
        assert decompress_string(compressed) == original

    def test_empty_string(self):
        compressed = compress_string("")
        assert decompress_string(compressed) == ""

    def test_unicode(self):
        original = "你好世界 🌍 émojis"
        assert decompress_string(compress_string(original)) == original

    def test_compression_reduces_size(self):
        long_text = "aaaaaaaaaa" * 1000
        compressed = compress_string(long_text)
        assert len(compressed) < len(long_text.encode("utf-8"))

    def test_compression_level_range(self):
        text = "test data"
        for level in range(1, 10):
            result = compress_string(text, level=level)
            assert decompress_string(result) == text

    def test_invalid_level_raises(self):
        with pytest.raises(ValueError, match="level must be between"):
            compress_string("x", level=0)
        with pytest.raises(ValueError, match="level must be between"):
            compress_string("x", level=10)

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="text must be a str"):
            compress_string(123)  # type: ignore[arg-type]

    def test_non_bytes_decompress_raises(self):
        with pytest.raises(TypeError, match="data must be bytes"):
            decompress_string("not bytes")  # type: ignore[arg-type]

    def test_cache_bypass(self):
        get_cache().clear()
        compress_string("no_cache_hit", use_cache=False)
        assert get_cache().stats["hits"] == 0

    def test_cache_hit_on_second_call(self):
        get_cache().clear()
        text = "cache_me"
        compress_string(text, use_cache=True)
        compress_string(text, use_cache=True)
        stats = get_cache().stats
        assert stats["hits"] >= 1
        assert stats["misses"] >= 1


# ── ThreadSafeLRUCache ───────────────────────────────────────────────────────


class TestLRUCache:
    def setup_method(self):
        self.cache = ThreadSafeLRUCache(maxsize=3, default_ttl=10.0)

    def test_put_and_get(self):
        self.cache.put("a", b"1")
        assert self.cache.get("a") == b"1"

    def test_miss_returns_none(self):
        assert self.cache.get("missing") is None

    def test_lru_eviction(self):
        self.cache.put("a", b"1")
        self.cache.put("b", b"2")
        self.cache.put("c", b"3")
        self.cache.put("d", b"4")  # evicts "a"
        assert self.cache.get("a") is None
        assert self.cache.get("d") == b"4"

    def test_access_refreshes_order(self):
        self.cache.put("a", b"1")
        self.cache.put("b", b"2")
        self.cache.put("c", b"3")
        self.cache.get("a")  # refresh "a"
        self.cache.put("d", b"4")  # evicts "b" (least recently used)
        assert self.cache.get("a") == b"1"
        assert self.cache.get("b") is None

    def test_overwrite_existing_key(self):
        self.cache.put("a", b"old")
        self.cache.put("a", b"new")
        assert self.cache.get("a") == b"new"
        assert self.cache.size == 1

    def test_ttl_expiry(self):
        cache = ThreadSafeLRUCache(maxsize=10, default_ttl=0.05)
        cache.put("k", b"v")
        time.sleep(0.1)
        assert cache.get("k") is None

    def test_per_entry_ttl(self):
        self.cache.put("short", b"s", ttl=0.05)
        self.cache.put("long", b"l", ttl=60.0)
        time.sleep(0.1)
        assert self.cache.get("short") is None
        assert self.cache.get("long") == b"l"

    def test_invalidate(self):
        self.cache.put("a", b"1")
        assert self.cache.invalidate("a") is True
        assert self.cache.get("a") is None
        assert self.cache.invalidate("a") is False

    def test_clear(self):
        self.cache.put("a", b"1")
        self.cache.put("b", b"2")
        self.cache.clear()
        assert self.cache.size == 0
        assert self.cache.get("a") is None

    def test_stats(self):
        self.cache.put("a", b"1")
        self.cache.get("a")  # hit
        self.cache.get("b")  # miss
        stats = self.cache.stats
        assert stats["hits"] == 1
        assert stats["misses"] == 1
        assert stats["hit_rate"] == pytest.approx(0.5)
        assert stats["size"] == 1

    def test_size_property(self):
        assert self.cache.size == 0
        self.cache.put("a", b"1")
        assert self.cache.size == 1

    def test_invalid_maxsize(self):
        with pytest.raises(ValueError, match="maxsize"):
            ThreadSafeLRUCache(maxsize=0)

    def test_invalid_ttl(self):
        with pytest.raises(ValueError, match="default_ttl"):
            ThreadSafeLRUCache(default_ttl=-1)


# ── Thread safety ────────────────────────────────────────────────────────────


class TestThreadSafety:
    def test_concurrent_writes(self):
        cache = ThreadSafeLRUCache(maxsize=100)
        errors: list[Exception] = []

        def writer(start: int):
            try:
                for i in range(200):
                    cache.put(f"key-{start + i}", f"val-{i}".encode())
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=writer, args=(t * 200,)) for t in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert errors == []
        assert cache.size <= 100

    def test_concurrent_reads_and_writes(self):
        cache = ThreadSafeLRUCache(maxsize=50, default_ttl=5.0)
        for i in range(50):
            cache.put(f"k{i}", f"v{i}".encode())

        errors: list[Exception] = []

        def reader():
            try:
                for _ in range(500):
                    cache.get("k25")
            except Exception as e:
                errors.append(e)

        def writer():
            try:
                for i in range(500):
                    cache.put(f"new-{i}", b"x")
            except Exception as e:
                errors.append(e)

        threads = [
            threading.Thread(target=reader),
            threading.Thread(target=reader),
            threading.Thread(target=writer),
            threading.Thread(target=writer),
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert errors == []

    def test_compress_string_thread_safety(self):
        get_cache().clear()
        results: dict[int, bytes] = {}
        errors: list[Exception] = []

        def compress_worker(idx: int, text: str):
            try:
                results[idx] = compress_string(text)
            except Exception as e:
                errors.append(e)

        texts = [f"thread-safety-test-{i}" * 10 for i in range(20)]
        threads = [
            threading.Thread(target=compress_worker, args=(i, t))
            for i, t in enumerate(texts)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert errors == []
        for idx, compressed in results.items():
            assert decompress_string(compressed) == texts[idx]
